namespace NovaHarvest.Core.Events; public enum GameEventType { MeteorShower, AlienSignal, MobMigration, NightInvasion, SolarStorm } public sealed class GameEvent { public GameEventType Type { get; } public string Title { get; } public string Description { get; } public int DangerLevel { get; } public GameEvent(GameEventType type, string title, string description, int dangerLevel) { Type = type; Title = title; Description = description; DangerLevel = dangerLevel; } }
